-- Korean locale additions for `page_text_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_page_text_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_page_text_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `Text` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;




UPDATE `page_text_locale` AS `l`
INNER JOIN `_koKR_stage_page_text_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
INNER JOIN `page_text` AS `p` ON `p`.`entry` = `s`.`ID`
SET `l`.`Text` = IF(`s`.`Text` IS NOT NULL AND (`l`.`Text` IS NULL OR `l`.`Text` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text`, `l`.`Text`);

SELECT `s`.`ID`, 'koKR', `s`.`Text`
FROM `_koKR_stage_page_text_locale` AS `s`
INNER JOIN `page_text` AS `p` ON `p`.`entry` = `s`.`ID`
LEFT JOIN `page_text_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_page_text_locale`;
